-- src/features/regulations/regulationTemplates.js; later versions are published
-- from the application by the platform owner.

insert into public.regulation_templates (key, title, title_en, category, description, sources, version, content, change_note)
values ('infection_control', 'Εσωτερικός Κανονισμός Πρόληψης και Ελέγχου Λοιμώξεων', 'Internal regulation for infection prevention and control', 'infection', 'Σύμφωνα με την Υ1.Γ.Π.114971 (ΦΕΚ Β΄ 388/2014) και τις οδηγίες σύνταξης του 2015: επιτροπές και αρμοδιότητες, επιτήρηση, μέτρα πρόληψης, ασφάλεια προσωπικού, αντιβιοτικά, εκπαίδευση.', 'Υ1.Γ.Π.114971 (ΦΕΚ Β΄ 388/18-2-2014) · Γ1α.ΓΠ.82706/2014 (26-3-2015) · Οδηγίες ΕΟΔΥ · Πρόγραμμα «Προκρούστης» · ECDC · ΠΟΥ', 1, '{"chapters":[{"id":"intro","title":"Εισαγωγή","sections":[{"id":"intro-purpose","title":"Ο Κανονισμός","html":"<p>Ο παρών Εσωτερικός Κανονισμός Πρόληψης και Ελέγχου Λοιμώξεων ορίζει τον τρόπο με τον οποίο το {hospital} προλαμβάνει, επιτηρεί και ελέγχει τις λοιμώξεις που συνδέονται με την παροχή υπηρεσιών υγείας (ΛΣΥΥ) και τη μικροβιακή αντοχή, σύμφωνα με την απόφαση Υ1.Γ.Π.114971 (ΦΕΚ Β΄ 388/18-2-2014) «Μέτρα, όροι και διαδικασίες για την πρόληψη και τον έλεγχο των λοιμώξεων που συνδέονται με τη νοσηλεία των ασθενών στους Χώρους Παροχής Υγείας».</p>\n<p>Ο Κανονισμός συγκεντρώνει σε ένα ελεγχόμενο έγγραφο:</p>\n<ul><li>τον ρόλο και τις αρμοδιότητες του ανθρώπινου δυναμικού,</li><li>τους δείκτες επιτήρησης των λοιμώξεων,</li><li>τα μέτρα πρόληψης και ελέγχου και τα πρωτόκολλα που τα εφαρμόζουν,</li><li>την πολιτική για την ορθολογική χρήση των αντιβιοτικών,</li><li>την εκπαίδευση του προσωπικού και το ετήσιο σχέδιο δράσης.</li></ul>\n<p>Ο Κανονισμός δεσμεύει όλο το προσωπικό, μόνιμο και συμβασιούχο, τους εκπαιδευόμενους και τους εξωτερικούς συνεργάτες που εργάζονται στους χώρους του {hospital}.</p>"}]},{"id":"a","title":"Κεφάλαιο Α. Βασικές αρχές","sections":[{"id":"a-scope","title":"Α.1 Σκοπός","html":"<p>Σκοπός του Κανονισμού είναι:</p>\n<ul><li>να περιγράψει με σαφήνεια τα μέτρα και τις διαδικασίες για την πρόληψη και τον έλεγχο των λοιμώξεων,</li><li>να καθορίσει τις αρμοδιότητες κάθε εμπλεκόμενου,</li><li>να ορίσει τους δείκτες που επιτηρούνται και τον τρόπο καταγραφής τους,</li><li>να εξασφαλίσει την ορθολογική χρήση των αντιβιοτικών,</li><li>να θέσει το πλαίσιο της εκπαίδευσης και της αξιολόγησης των αποτελεσμάτων.</li></ul>"},{"id":"a-terms","title":"Α.2 Ορισμοί","html":"<p><strong>Λοίμωξη σχετιζόμενη με την παροχή υπηρεσιών υγείας (ΛΣΥΥ):</strong> λοίμωξη που δεν υπήρχε ούτε επωαζόταν κατά την εισαγωγή του ασθενούς και εκδηλώνεται κατά τη νοσηλεία ή μετά την έξοδο, σύμφωνα με τους ορισμούς του ECDC.</p>\n<p><strong>Πολυανθεκτικοί μικροοργανισμοί (MDRO):</strong> μικροοργανισμοί ανθεκτικοί σε μία ή περισσότερες κατηγορίες αντιμικροβιακών, όπως MRSA, VRE, εντεροβακτηριακά που παράγουν καρβαπενεμάσες (CPE), πολυανθεκτικά Acinetobacter baumannii και Pseudomonas aeruginosa.</p>\n<p><strong>Βασικές προφυλάξεις:</strong> το ελάχιστο σύνολο μέτρων που εφαρμόζεται σε κάθε ασθενή, ανεξάρτητα από τη διάγνωση.</p>\n<p><strong>Προφυλάξεις κατά τη μετάδοση:</strong> πρόσθετα μέτρα επαφής, σταγονιδίων ή αερογενούς μετάδοσης, ανάλογα με τον μικροοργανισμό.</p>"},{"id":"a-framework","title":"Α.3 Νομοθετικό και κανονιστικό πλαίσιο","html":"<ul><li>Υ1.Γ.Π.114971 (ΦΕΚ Β΄ 388/18-2-2014): μέτρα, όροι και διαδικασίες για την πρόληψη και τον έλεγχο των λοιμώξεων στους Χώρους Παροχής Υγείας.</li><li>Γ1α.ΓΠ.82706/2014 (26-3-2015): οδηγίες για τη σύνταξη του Εσωτερικού Κανονισμού Πρόληψης και Ελέγχου Λοιμώξεων.</li><li>ΚΥΑ 146163/2012 (ΦΕΚ Β΄ 1537), όπως ισχύει: διαχείριση αποβλήτων υγειονομικών μονάδων.</li><li>Οδηγίες και κατευθυντήριες οδηγίες του ΕΟΔΥ και του Προγράμματος «Προκρούστης» για τα πολυανθεκτικά παθογόνα.</li><li>Οδηγίες του ECDC και του Παγκόσμιου Οργανισμού Υγείας για την υγιεινή των χεριών και τον έλεγχο λοιμώξεων.</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: τυχόν πρόσθετες αποφάσεις του Διοικητικού Συμβουλίου ή της Διοίκησης του νοσοκομείου.</p>"}]},{"id":"b","title":"Κεφάλαιο Β. Πολιτική και στρατηγική","sections":[{"id":"b-policy","title":"Β.1 Πολιτική του νοσοκομείου","html":"<p>Η Διοίκηση του {hospital} δεσμεύεται ότι η πρόληψη και ο έλεγχος των λοιμώξεων αποτελούν προτεραιότητα για την ασφάλεια των ασθενών και του προσωπικού. Για τον σκοπό αυτό:</p>\n<ul><li>εξασφαλίζει τους πόρους, το προσωπικό και τον εξοπλισμό που απαιτεί το πρόγραμμα,</li><li>εγκρίνει κάθε χρόνο το Σχέδιο Δράσης της Επιτροπής Νοσοκομειακών Λοιμώξεων,</li><li>παρακολουθεί τους δείκτες και τα αποτελέσματα στην Ανασκόπηση της Διοίκησης,</li><li>στηρίζει την κουλτούρα ασφάλειας χωρίς απόδοση ευθύνης για την αναφορά συμβάντων.</li></ul>"},{"id":"b-targets","title":"Β.2 Στόχοι","html":"<p>Οι στόχοι ορίζονται ετησίως, είναι μετρήσιμοι και παρακολουθούνται στο Κέντρο Ποιότητας. Ενδεικτικά:</p>\n<ul><li>συμμόρφωση στην υγιεινή των χεριών άνω του 80% σε κάθε τμήμα,</li><li>μείωση της επίπτωσης των βακτηριαιμιών από κεντρικό φλεβικό καθετήρα,</li><li>κατανάλωση αλκοολούχου αντισηπτικού τουλάχιστον 20 λίτρα ανά 1.000 ημέρες νοσηλείας,</li><li>μείωση της κατανάλωσης αντιβιοτικών ευρέος φάσματος (DDD/100 ημέρες νοσηλείας).</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: τους στόχους του τρέχοντος έτους, όπως εγκρίθηκαν.</p>"}]},{"id":"c","title":"Κεφάλαιο Γ. Ανθρώπινοι πόροι και αρμοδιότητες","sections":[{"id":"c-enl","title":"Γ.1 Επιτροπή Νοσοκομειακών Λοιμώξεων (ΕΝΛ)","html":"<p>Η ΕΝΛ είναι το όργανο που σχεδιάζει, συντονίζει και αξιολογεί το πρόγραμμα πρόληψης και ελέγχου λοιμώξεων. Συγκροτείται με απόφαση της Διοίκησης και συνεδριάζει τουλάχιστον μία φορά τον μήνα.</p>\n<p>Η ΕΝΛ:</p>\n<ul><li>καταρτίζει και αναθεωρεί τον Εσωτερικό Κανονισμό,</li><li>εγκρίνει τα πρωτόκολλα και τις διαδικασίες,</li><li>συντάσσει το ετήσιο Σχέδιο Δράσης και την ετήσια έκθεση πεπραγμένων,</li><li>αξιολογεί τα αποτελέσματα της επιτήρησης και αποφασίζει διορθωτικές ενέργειες,</li><li>διερευνά επιδημίες και ορίζει τα μέτρα ελέγχου τους.</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: τη σύνθεση της ΕΝΛ (πρόεδρος, μέλη, γραμματέας) και την απόφαση συγκρότησης.</p>"},{"id":"c-oekoxa","title":"Γ.2 Ομάδα Επιτήρησης Κατανάλωσης και Ορθολογικής Χρήσης Αντιβιοτικών (ΟΕΚΟΧΑ)","html":"<p>Η ΟΕΚΟΧΑ παρακολουθεί την κατανάλωση των αντιβιοτικών, εγκρίνει τη θεραπευτική πολιτική και επανεξετάζει τις συνταγές των αντιβιοτικών περιορισμένης χρήσης. Σε αυτήν συμμετέχουν τουλάχιστον ένας λοιμωξιολόγος ή ιατρός με εμπειρία στις λοιμώξεις, ο υπεύθυνος του Φαρμακείου και ο υπεύθυνος του Μικροβιολογικού Εργαστηρίου.</p>"},{"id":"c-nurses","title":"Γ.3 Νοσηλευτές Επιτήρησης Λοιμώξεων","html":"<p>Οι Νοσηλευτές Επιτήρησης Λοιμώξεων υλοποιούν καθημερινά το πρόγραμμα:</p>\n<ul><li>καταγράφουν τις λοιμώξεις και τους πολυανθεκτικούς μικροοργανισμούς σε όλα τα τμήματα,</li><li>ελέγχουν την εφαρμογή των μέτρων απομόνωσης,</li><li>διενεργούν παρατηρήσεις υγιεινής των χεριών και ελέγχους συμμόρφωσης,</li><li>εκπαιδεύουν το προσωπικό στο τμήμα,</li><li>ενημερώνουν άμεσα την ΕΝΛ για κάθε ασυνήθιστη συρροή κρουσμάτων.</li></ul>\n<p>Σύμφωνα με το ισχύον πλαίσιο, προβλέπεται ένας νοσηλευτής επιτήρησης ανά 250 κλίνες, και ανά 90 κλίνες για τις μονάδες υψηλού κινδύνου.</p>"},{"id":"c-all","title":"Γ.4 Υποχρεώσεις του προσωπικού","html":"<p>Κάθε εργαζόμενος:</p>\n<ul><li>τηρεί τις βασικές προφυλάξεις και την υγιεινή των χεριών στις πέντε ενδείξεις,</li><li>εφαρμόζει τις οδηγίες απομόνωσης που ορίζει η ΕΝΛ,</li><li>συμμετέχει στην υποχρεωτική εκπαίδευση,</li><li>αναφέρει κάθε έκθεση σε βιολογικό υλικό και κάθε συμβάν,</li><li>ενημερώνεται για τις αναθεωρήσεις του Κανονισμού.</li></ul>\n<p>Οι Διευθυντές και οι Προϊστάμενοι των τμημάτων είναι υπεύθυνοι για την εφαρμογή του Κανονισμού στο τμήμα τους και ορίζουν νοσηλευτή σύνδεσμο (link nurse) με την ΕΝΛ.</p>"}]},{"id":"d","title":"Κεφάλαιο Δ. Επιτήρηση λοιμώξεων","sections":[{"id":"d-system","title":"Δ.1 Σύστημα επιτήρησης","html":"<p>Η επιτήρηση είναι συνεχής, ενεργητική και βασίζεται σε ορισμούς του ECDC, ώστε τα αποτελέσματα να συγκρίνονται με τα εθνικά και ευρωπαϊκά δεδομένα. Οι πηγές είναι τα αποτελέσματα του Μικροβιολογικού Εργαστηρίου, οι ενημερώσεις των τμημάτων και οι επισκέψεις των Νοσηλευτών Επιτήρησης.</p>"},{"id":"d-indicators","title":"Δ.2 Υποχρεωτικοί δείκτες","html":"<p>Παρακολουθούνται τουλάχιστον:</p>\n<ul><li>η επίπτωση των πολυανθεκτικών μικροοργανισμών ανά 1.000 ημέρες νοσηλείας,</li><li>οι βακτηριαιμίες από κεντρικό φλεβικό καθετήρα (CLABSI) στις ΜΕΘ,</li><li>οι πνευμονίες σχετιζόμενες με μηχανικό αερισμό (VAP),</li><li>οι ουρολοιμώξεις από ουροκαθετήρα (CAUTI),</li><li>οι λοιμώξεις του χειρουργικού πεδίου στις επεμβάσεις που επιτηρούνται,</li><li>η κατανάλωση αλκοολούχου αντισηπτικού και η συμμόρφωση στην υγιεινή των χεριών,</li><li>η κατανάλωση αντιβιοτικών σε DDD/100 ημέρες νοσηλείας.</li></ul>"},{"id":"d-reporting","title":"Δ.3 Δήλωση και ανατροφοδότηση","html":"<p>Τα αποτελέσματα παρουσιάζονται κάθε μήνα στην ΕΝΛ και κοινοποιούνται στα τμήματα. Οι υποχρεωτικές δηλώσεις προς τον ΕΟΔΥ γίνονται στις προθεσμίες που ορίζει ο ΕΟΔΥ. Η συρροή δύο ή περισσότερων κρουσμάτων με τον ίδιο μικροοργανισμό στο ίδιο τμήμα διερευνάται ως πιθανή επιδημία.</p>"}]},{"id":"e","title":"Κεφάλαιο Ε. Μέτρα πρόληψης και ελέγχου","sections":[{"id":"e-hands","title":"Ε.1 Υγιεινή των χεριών","html":"<p>Η υγιεινή των χεριών εφαρμόζεται στις πέντε ενδείξεις του Παγκόσμιου Οργανισμού Υγείας: πριν από την επαφή με τον ασθενή, πριν από άσηπτο χειρισμό, μετά από έκθεση σε βιολογικά υγρά, μετά την επαφή με τον ασθενή και μετά την επαφή με το περιβάλλον του.</p>\n<ul><li>Το αλκοολούχο αντισηπτικό είναι η πρώτη επιλογή· πλύσιμο με νερό και σαπούνι όταν τα χέρια είναι εμφανώς λερωμένα ή μετά από φροντίδα ασθενούς με Clostridioides difficile.</li><li>Δεν επιτρέπονται τεχνητά νύχια, δαχτυλίδια, ρολόγια και βραχιόλια κατά τη φροντίδα ασθενών.</li><li>Η συμμόρφωση μετριέται με άμεση παρατήρηση και κοινοποιείται στα τμήματα.</li></ul>"},{"id":"e-standard","title":"Ε.2 Βασικές προφυλάξεις","html":"<ul><li>Χρήση γαντιών, ποδιάς, μάσκας και προστασίας ματιών ανάλογα με τον κίνδυνο έκθεσης.</li><li>Ασφαλής χρήση και απόρριψη αιχμηρών σε ειδικούς περιέκτες, χωρίς επανατοποθέτηση του καλύμματος της βελόνας.</li><li>Υγιεινή του αναπνευστικού και ευγένεια του βήχα.</li><li>Καθαρισμός και απολύμανση του εξοπλισμού μεταξύ ασθενών.</li><li>Ασφαλείς ενέσεις: μία σύριγγα και μία βελόνα για κάθε ασθενή και κάθε χρήση.</li></ul>"},{"id":"e-isolation","title":"Ε.3 Προφυλάξεις κατά τη μετάδοση και απομόνωση","html":"<p>Οι προφυλάξεις επαφής, σταγονιδίων ή αερογενούς μετάδοσης εφαρμόζονται μόλις τεθεί η υποψία, χωρίς να αναμένεται η επιβεβαίωση. Ο ασθενής νοσηλεύεται σε μονόκλινο θάλαμο ή σε ομαδική νοσηλεία (cohorting) με ασθενείς με τον ίδιο μικροοργανισμό, και η κατάσταση σημαίνεται στη θύρα και στον φάκελο.</p>\n<p>Για τα πολυανθεκτικά παθογόνα εφαρμόζεται το Πρόγραμμα «Προκρούστης»: ενεργητική επιτήρηση με καλλιέργειες επιτήρησης κατά την εισαγωγή των ασθενών υψηλού κινδύνου, απομόνωση, αποκλειστικός εξοπλισμός και ενημέρωση κατά τη διακομιδή.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τη διαθεσιμότητα θαλάμων απομόνωσης και τη διαδικασία κατανομής τους.</p>"},{"id":"e-bundles","title":"Ε.4 Δέσμες μέτρων (bundles)","html":"<p>Για την πρόληψη των λοιμώξεων από επεμβατικές συσκευές εφαρμόζονται δέσμες μέτρων και η τήρησή τους καταγράφεται:</p>\n<ul><li>τοποθέτηση και συντήρηση κεντρικού φλεβικού καθετήρα,</li><li>πρόληψη της πνευμονίας σε μηχανικό αερισμό (ανύψωση κεφαλής 30°–45°, καθημερινή εκτίμηση της αποσωλήνωσης, στοματική φροντίδα),</li><li>ουροκαθετήρας μόνο με ένδειξη και καθημερινή επανεκτίμηση της ανάγκης,</li><li>πρόληψη της λοίμωξης του χειρουργικού πεδίου (αποτρίχωση με κουρευτική μηχανή, προφυλακτική αντιβίωση εντός 60 λεπτών πριν από την τομή, νορμοθερμία).</li></ul>"},{"id":"e-environment","title":"Ε.5 Καθαριότητα και απολύμανση του περιβάλλοντος","html":"<p>Ο καθαρισμός γίνεται με γραπτό πρόγραμμα ανά χώρο και συχνότητα, με κωδικοποίηση χρωμάτων για τα υλικά και ελέγχους της ποιότητας. Μετά την έξοδο ασθενούς με πολυανθεκτικό μικροοργανισμό ή Clostridioides difficile γίνεται τελικός καθαρισμός και απολύμανση του θαλάμου με σκεύασμα που ορίζει η ΕΝΛ.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τον ανάδοχο ή το τμήμα καθαριότητας, τα σκευάσματα που χρησιμοποιούνται και τη συχνότητα ελέγχων.</p>"},{"id":"e-sterilization","title":"Ε.6 Αποστείρωση και επαναχρησιμοποιούμενα υλικά","html":"<p>Τα επαναχρησιμοποιούμενα ιατροτεχνολογικά προϊόντα επεξεργάζονται στην Κεντρική Αποστείρωση με επικυρωμένες μεθόδους. Κάθε κύκλος τεκμηριώνεται με φυσικούς, χημικούς και βιολογικούς δείκτες και τα υλικά ιχνηλατούνται έως τον ασθενή. Τα ενδοσκόπια υφίστανται υψηλού βαθμού απολύμανση σε πλυντήρια ενδοσκοπίων και ο έλεγχός τους καταγράφεται.</p>"},{"id":"e-water","title":"Ε.7 Νερό, κλιματισμός και εργασίες","html":"<p>Εφαρμόζεται σχέδιο ασφάλειας νερού για την πρόληψη της λεγιονέλλωσης, με περιοδικές δειγματοληψίες και μέτρα στα σημεία υψηλού κινδύνου. Οι οικοδομικές εργασίες και οι ανακαινίσεις προηγούνται από εκτίμηση κινδύνου λοιμώξεων με τη συμμετοχή της ΕΝΛ.</p>"},{"id":"e-waste","title":"Ε.8 Απόβλητα υγειονομικών μονάδων","html":"<p>Τα απόβλητα διαχωρίζονται στο σημείο παραγωγής σύμφωνα με τον Εσωτερικό Κανονισμό Διαχείρισης Αποβλήτων του {hospital} και την ΚΥΑ 146163/2012, όπως ισχύει. Τα αιχμηρά απορρίπτονται πάντα σε άκαμπτους περιέκτες, που κλείνονται όταν γεμίσουν κατά τα τρία τέταρτα.</p>"}]},{"id":"f","title":"Κεφάλαιο ΣΤ. Ασφάλεια του προσωπικού","sections":[{"id":"f-vaccines","title":"ΣΤ.1 Εμβολιασμοί","html":"<p>Το προσωπικό ενθαρρύνεται να εμβολιάζεται σύμφωνα με το Εθνικό Πρόγραμμα Εμβολιασμών Ενηλίκων: ηπατίτιδα Β (με έλεγχο αντισωμάτων), ετήσιος αντιγριπικός εμβολιασμός, ιλαρά-παρωτίτιδα-ερυθρά, ανεμευλογιά, διφθερίτιδα-τέτανος-κοκκύτης και όσοι άλλοι συστήνονται. Η εμβολιαστική κάλυψη καταγράφεται από την Ιατρική της Εργασίας.</p>"},{"id":"f-exposure","title":"ΣΤ.2 Έκθεση σε αίμα και βιολογικά υγρά","html":"<p>Μετά από τρύπημα με βελόνα ή έκθεση βλεννογόνου:</p>\n<ul><li>πλύσιμο της περιοχής με νερό και σαπούνι ή άφθονο φυσιολογικό ορό για τους βλεννογόνους,</li><li>άμεση αναφορά στον προϊστάμενο και στον Ιατρό Εργασίας,</li><li>εκτίμηση του κινδύνου και έναρξη προφύλαξης μετά την έκθεση, όταν ενδείκνυται, το συντομότερο (ιδανικά εντός δύο ωρών),</li><li>παρακολούθηση του εργαζομένου σύμφωνα με το πρωτόκολλο.</li></ul>"},{"id":"f-ppe","title":"ΣΤ.3 Μέσα ατομικής προστασίας","html":"<p>Το νοσοκομείο διαθέτει επαρκή μέσα ατομικής προστασίας, ενώ το προσωπικό εκπαιδεύεται στη σωστή σειρά ένδυσης και αφαίρεσής τους. Για τους αερογενώς μεταδιδόμενους μικροοργανισμούς χρησιμοποιούνται μάσκες FFP2/FFP3 με έλεγχο εφαρμογής.</p>"}]},{"id":"g","title":"Κεφάλαιο Ζ. Ορθολογική χρήση αντιβιοτικών","sections":[{"id":"g-stewardship","title":"Ζ.1 Πρόγραμμα επιτήρησης (antimicrobial stewardship)","html":"<ul><li>Εμπειρική θεραπεία σύμφωνα με τις τοπικές κατευθυντήριες οδηγίες, που βασίζονται στα δεδομένα αντοχής του νοσοκομείου.</li><li>Λήψη καλλιεργειών πριν από την έναρξη αντιβιοτικών, όπου είναι δυνατόν.</li><li>Επανεκτίμηση της θεραπείας στις 48–72 ώρες και αποκλιμάκωση με βάση τα αποτελέσματα.</li><li>Ειδικό έντυπο αιτιολόγησης για τα αντιβιοτικά περιορισμένης χρήσης, που εγκρίνει η ΟΕΚΟΧΑ.</li><li>Χειρουργική προφύλαξη: μία δόση, ή έως 24 ώρες, εκτός αν ορίζεται διαφορετικά.</li></ul>"},{"id":"g-data","title":"Ζ.2 Δεδομένα κατανάλωσης και αντοχής","html":"<p>Το Φαρμακείο υπολογίζει κάθε τρίμηνο την κατανάλωση σε DDD/100 ημέρες νοσηλείας ανά τμήμα και κατηγορία. Το Μικροβιολογικό Εργαστήριο εκδίδει ετησίως τον αντιβιογραμματικό χάρτη (antibiogram) του νοσοκομείου. Τα δύο αξιολογούνται μαζί από την ΟΕΚΟΧΑ.</p>"}]},{"id":"h","title":"Κεφάλαιο Η. Εκπαίδευση","sections":[{"id":"h-program","title":"Η.1 Πρόγραμμα εκπαίδευσης","html":"<ul><li>Εισαγωγική εκπαίδευση κάθε νεοπροσλαμβανόμενου πριν από την ανάληψη καθηκόντων.</li><li>Ετήσια υποχρεωτική εκπαίδευση όλου του προσωπικού στην υγιεινή των χεριών και τις βασικές προφυλάξεις.</li><li>Στοχευμένη εκπαίδευση μετά από επιδημία ή αποτυχία σε έλεγχο.</li><li>Ενημέρωση ασθενών και επισκεπτών με έντυπο υλικό και αφίσες.</li></ul>\n<p>Η παρακολούθηση καταγράφεται στην ενότητα Εκπαίδευση και η αποτελεσματικότητα αξιολογείται με τους δείκτες συμμόρφωσης.</p>"}]},{"id":"i","title":"Κεφάλαιο Θ. Εφαρμογή και αναθεώρηση","sections":[{"id":"i-plan","title":"Θ.1 Ετήσιο Σχέδιο Δράσης","html":"<p>Η ΕΝΛ υποβάλλει κάθε χρόνο στη Διοίκηση Σχέδιο Δράσης με στόχους, ενέργειες, υπευθύνους και χρονοδιάγραμμα, μαζί με την έκθεση πεπραγμένων του προηγούμενου έτους.</p>"},{"id":"i-review","title":"Θ.2 Αναθεώρηση του Κανονισμού","html":"<p>Ο Κανονισμός αναθεωρείται τουλάχιστον κάθε δύο χρόνια, και νωρίτερα όταν αλλάζει το νομοθετικό πλαίσιο, οι κατευθυντήριες οδηγίες ή η επιδημιολογική εικόνα. Κάθε έκδοση εγκρίνεται από τη Διοίκηση, και η ισχύουσα είναι πάντα αυτή που εμφανίζεται εδώ. Τα έντυπα αντίγραφα είναι μη ελεγχόμενα.</p>"}]},{"id":"annex","title":"Παραρτήματα","sections":[{"id":"annex-forms","title":"Σχετικά έντυπα και διαδικασίες","html":"<p>Στο παράρτημα παρατίθενται τα έντυπα και οι διαδικασίες που εφαρμόζουν τον Κανονισμό. Ενδεικτικά:</p>\n<ul><li>διαδικασία καθαρισμού θαλάμου απομόνωσης,</li><li>έντυπο παρατήρησης υγιεινής των χεριών,</li><li>έντυπο δήλωσης έκθεσης σε βιολογικό υλικό,</li><li>έντυπο αιτιολόγησης αντιβιοτικών περιορισμένης χρήσης,</li><li>λίστα ελέγχου τοποθέτησης κεντρικού φλεβικού καθετήρα.</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: τα δικά σας έντυπα, με κωδικό και έκδοση.</p>"}]}]}'::jsonb, 'Πρώτη έκδοση του προτύπου.')
on conflict (key) do nothing;
insert into public.regulation_template_versions (template_key, version, content, change_note, published_by)
select key, version, content, change_note, null from public.regulation_templates where key = 'infection_control'
on conflict (template_key, version) do nothing;

insert into public.regulation_templates (key, title, title_en, category, description, sources, version, content, change_note)
values ('healthcare_waste', 'Εσωτερικός Κανονισμός Διαχείρισης Αποβλήτων Υγειονομικής Μονάδας', 'Internal regulation for healthcare waste management', 'waste', 'Σύμφωνα με την ΚΥΑ 146163/2012 (ΦΕΚ Β΄ 1537), όπως ισχύει: κατηγορίες και χρωματικός κώδικας, διαχωρισμός, συλλογή, αποθήκευση, αρμοδιότητες, δείκτες.', 'ΚΥΑ 146163/2012 (ΦΕΚ Β΄ 1537/8-5-2012), όπως ισχύει · Ν. 4042/2012 · Ν. 4819/2021 · Ηλεκτρονικό Μητρώο Αποβλήτων', 1, '{"chapters":[{"id":"w-intro","title":"Εισαγωγή","sections":[{"id":"w-purpose","title":"Σκοπός και πεδίο εφαρμογής","html":"<p>Ο Εσωτερικός Κανονισμός Διαχείρισης Αποβλήτων ορίζει πώς το {hospital} διαχωρίζει, συσκευάζει, συλλέγει, αποθηκεύει προσωρινά και παραδίδει τα απόβλητα που παράγει, ώστε να προστατεύονται οι ασθενείς, το προσωπικό, η δημόσια υγεία και το περιβάλλον, σύμφωνα με την ΚΥΑ 146163/2012 (ΦΕΚ Β΄ 1537/8-5-2012) «Μέτρα και όροι για τη διαχείριση αποβλήτων υγειονομικών μονάδων», όπως ισχύει.</p>\n<p>Εφαρμόζεται σε όλα τα τμήματα, τα εργαστήρια και τους βοηθητικούς χώρους, καθώς και σε όσους συνεργάζονται με το νοσοκομείο για τη συλλογή και τη μεταφορά των αποβλήτων.</p>"},{"id":"w-framework","title":"Νομοθετικό πλαίσιο","html":"<ul><li>ΚΥΑ 146163/2012 (ΦΕΚ Β΄ 1537), όπως τροποποιήθηκε και ισχύει.</li><li>Ν. 4042/2012 για την προστασία του περιβάλλοντος μέσω του ποινικού δικαίου και το πλαίσιο παραγωγής και διαχείρισης αποβλήτων.</li><li>Ν. 4819/2021 για τη χωριστή συλλογή των ανακυκλώσιμων και των λοιπών ρευμάτων αποβλήτων και οι διευκρινίσεις του Υπουργείου Υγείας για τις υγειονομικές μονάδες.</li><li>Το Ηλεκτρονικό Μητρώο Αποβλήτων (ΗΜΑ) για την ετήσια έκθεση παραγωγού.</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: τυχόν αποφάσεις της Περιφέρειας ή της οικείας Υγειονομικής Περιφέρειας.</p>"}]},{"id":"w-categories","title":"Κατηγορίες αποβλήτων","sections":[{"id":"w-cat-list","title":"Κατηγορίες και χρωματικός κώδικας","html":"<p>Τα απόβλητα διαχωρίζονται στο σημείο παραγωγής στις εξής κατηγορίες:</p>\n<ul><li><strong>Μη επικίνδυνα, αστικού τύπου</strong> (υπολείμματα τροφών, χαρτιά, συσκευασίες χωρίς επιμόλυνση): μαύρος σάκος.</li><li><strong>Ανακυκλώσιμα</strong> (χαρτί, πλαστικό, γυαλί, μέταλλο χωρίς επιμόλυνση): μπλε κάδος ή κάδος ανά ρεύμα, σύμφωνα με το πρόγραμμα ανακύκλωσης.</li><li><strong>Επικίνδυνα απόβλητα αμιγώς μολυσματικά (ΕΑΑΜ)</strong> (υλικά επιμολυσμένα με αίμα ή βιολογικά υγρά, αιχμηρά, καλλιέργειες): κίτρινος περιέκτης ή σάκος με το σήμα του βιολογικού κινδύνου· τα αιχμηρά σε κίτρινους άκαμπτους περιέκτες.</li><li><strong>Μικτά επικίνδυνα απόβλητα (ΜΕΑ)</strong>, μολυσματικά και τοξικά μαζί (π.χ. υλικά από χορήγηση κυτταροτοξικών), και <strong>άλλα επικίνδυνα απόβλητα (ΑΕΑ)</strong> (χημικά, ληγμένα φάρμακα, υδράργυρος, μπαταρίες): κόκκινος περιέκτης.</li><li><strong>Ειδικά ρεύματα</strong> (απόβλητα ηλεκτρικού εξοπλισμού, λαμπτήρες, λάδια, ακτινολογικά υγρά): χωριστή συλλογή μέσω αδειοδοτημένων φορέων.</li></ul>\n<p class=\"reg-note\">Επιβεβαιώστε τον χρωματικό κώδικα με το ισχύον πλαίσιο και τον ανάδοχο επεξεργασίας πριν από την έγκριση.</p>"}]},{"id":"w-handling","title":"Διαχείριση στο νοσοκομείο","sections":[{"id":"w-segregation","title":"Διαχωρισμός και συσκευασία","html":"<ul><li>Ο διαχωρισμός γίνεται από αυτόν που παράγει το απόβλητο, τη στιγμή που το παράγει.</li><li>Οι περιέκτες γεμίζουν έως τα τρία τέταρτα, κλείνουν ερμητικά και σημαίνονται με το τμήμα και την ημερομηνία.</li><li>Δεν επιτρέπεται η μεταφορά αποβλήτων από περιέκτη σε περιέκτη, ούτε η συμπίεσή τους με το χέρι.</li><li>Τα αιχμηρά δεν τοποθετούνται ποτέ σε σάκους.</li></ul>"},{"id":"w-collection","title":"Εσωτερική συλλογή και μεταφορά","html":"<p>Η συλλογή γίνεται με καθορισμένο πρόγραμμα και διαδρομές που αποφεύγουν τους χώρους ασθενών και τροφίμων, με τροχήλατους κάδους που καθαρίζονται και απολυμαίνονται τακτικά.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τις ώρες συλλογής ανά όροφο, τη διαδρομή και τον υπεύθυνο.</p>"},{"id":"w-storage","title":"Προσωρινή αποθήκευση","html":"<p>Τα ΕΑΑΜ αποθηκεύονται σε κλειστό, ψυχόμενο ή κλιματιζόμενο χώρο με περιορισμένη πρόσβαση, για το διάστημα που επιτρέπει το ισχύον πλαίσιο, ανάλογα με τη θερμοκρασία αποθήκευσης. Ο χώρος σημαίνεται, πλένεται και απολυμαίνεται τακτικά και διαθέτει μέσα για την αντιμετώπιση διαρροών.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τη θέση του χώρου, τη θερμοκρασία και το μέγιστο διάστημα αποθήκευσης που εφαρμόζετε.</p>"},{"id":"w-spills","title":"Διαρροές και ατυχήματα","html":"<p>Σε διαρροή ή θραύση περιέκτη, ο χώρος απομονώνεται, το προσωπικό φορά τα κατάλληλα μέσα ατομικής προστασίας και χρησιμοποιεί το κιτ διαρροών. Κάθε συμβάν αναφέρεται στον Υπεύθυνο Διαχείρισης Αποβλήτων και καταγράφεται ως συμβάν στο Κέντρο Ποιότητας.</p>"}]},{"id":"w-roles","title":"Αρμοδιότητες","sections":[{"id":"w-officer","title":"Υπεύθυνος Διαχείρισης Αποβλήτων","html":"<p>Ο Υπεύθυνος ορίζεται από τη Διοίκηση και:</p>\n<ul><li>εποπτεύει την εφαρμογή του Κανονισμού,</li><li>συνεργάζεται με τους αδειοδοτημένους φορείς συλλογής, μεταφοράς και επεξεργασίας,</li><li>τηρεί τα έντυπα αναγνώρισης και παράδοσης και το μητρώο αποβλήτων,</li><li>υποβάλλει την ετήσια έκθεση στο Ηλεκτρονικό Μητρώο Αποβλήτων,</li><li>εκπαιδεύει το προσωπικό σε συνεργασία με την ΕΝΛ.</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: το όνομα και τη θέση του Υπευθύνου και του αναπληρωτή του.</p>"},{"id":"w-departments","title":"Τμήματα και προσωπικό","html":"<p>Οι Προϊστάμενοι των τμημάτων εξασφαλίζουν την επάρκεια περιεκτών και τον σωστό διαχωρισμό. Το προσωπικό καθαριότητας συλλέγει μόνο κλειστούς και σημασμένους περιέκτες και φορά πάντα γάντια και ποδιά.</p>"}]},{"id":"w-monitoring","title":"Παρακολούθηση","sections":[{"id":"w-indicators","title":"Δείκτες και έλεγχοι","html":"<ul><li>Παραγόμενη ποσότητα ΕΑΑΜ σε κιλά ανά κλίνη και ημέρα, ανά τμήμα.</li><li>Ποσοστό σωστού διαχωρισμού στους δειγματοληπτικούς ελέγχους.</li><li>Συμβάντα τραυματισμού από αιχμηρά.</li><li>Ποσότητες ανακυκλώσιμων ανά ρεύμα.</li></ul>\n<p>Οι δείκτες καταγράφονται μηνιαία, αξιολογούνται στην Ανασκόπηση της Διοίκησης και τροφοδοτούν τους στόχους μείωσης.</p>"},{"id":"w-review","title":"Αναθεώρηση","html":"<p>Ο Κανονισμός αναθεωρείται όταν αλλάζει το νομοθετικό πλαίσιο, ο ανάδοχος επεξεργασίας ή οι υπηρεσίες του νοσοκομείου, και σε κάθε περίπτωση τουλάχιστον κάθε δύο χρόνια.</p>"}]}]}'::jsonb, 'Πρώτη έκδοση του προτύπου.')
