on conflict (template_key, version) do nothing;

insert into public.regulation_templates (key, title, title_en, category, description, sources, version, content, change_note)
values ('food_safety', 'Κανονισμός Υγιεινής και Ασφάλειας Τροφίμων (HACCP)', 'Food hygiene and safety regulation (HACCP)', 'food', 'Σύμφωνα με τον Κανονισμό (ΕΚ) 852/2004 και τις αρχές HACCP: κρίσιμα σημεία ελέγχου, θερμοκρασίες, προαπαιτούμενα, δίαιτες και αλλεργιογόνα, διανομή στους θαλάμους.', 'Κανονισμός (ΕΚ) 852/2004 · Κανονισμός (ΕΚ) 178/2002 · Κανονισμός (ΕΕ) 1169/2011 · Οδηγοί ΕΦΕΤ · ISO 22000', 1, '{"chapters":[{"id":"f-intro","title":"Εισαγωγή","sections":[{"id":"f-purpose","title":"Σκοπός και πεδίο εφαρμογής","html":"<p>Ο Κανονισμός ορίζει πώς το {hospital} εξασφαλίζει ότι τα γεύματα που παρασκευάζει ή προμηθεύεται είναι ασφαλή, από την παραλαβή των πρώτων υλών έως το σερβίρισμα στον ασθενή, σύμφωνα με τον Κανονισμό (ΕΚ) 852/2004 για την υγιεινή των τροφίμων και τις αρχές HACCP.</p>\n<p>Αφορά την κεντρική κουζίνα, τα κυλικεία, τις κουζίνες ορόφων (offices), τη διανομή των γευμάτων και κάθε ανάδοχο εστίασης.</p>"},{"id":"f-framework","title":"Νομοθετικό πλαίσιο","html":"<ul><li>Κανονισμός (ΕΚ) 852/2004 για την υγιεινή των τροφίμων και Κανονισμός (ΕΚ) 178/2002 για τις γενικές αρχές της νομοθεσίας τροφίμων.</li><li>Κανονισμός (ΕΕ) 1169/2011 για την πληροφόρηση των καταναλωτών, και ειδικά για τα αλλεργιογόνα.</li><li>Οδηγοί υγιεινής και οδηγίες του Ενιαίου Φορέα Ελέγχου Τροφίμων (ΕΦΕΤ).</li><li>Προαιρετικά: ISO 22000 για συστήματα διαχείρισης ασφάλειας τροφίμων.</li></ul>"}]},{"id":"f-haccp","title":"Σύστημα HACCP","sections":[{"id":"f-team","title":"Ομάδα HACCP και ανάλυση κινδύνων","html":"<p>Η ομάδα HACCP (υπεύθυνος κουζίνας, διαιτολόγος, εκπρόσωπος της ΕΝΛ και της Ποιότητας) καταγράφει το διάγραμμα ροής κάθε κατηγορίας γεύματος, αναλύει τους βιολογικούς, χημικούς, φυσικούς κινδύνους και τους κινδύνους από αλλεργιογόνα, και ορίζει τα κρίσιμα σημεία ελέγχου.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τα μέλη της ομάδας HACCP και την ημερομηνία της τελευταίας ανασκόπησης.</p>"},{"id":"f-ccp","title":"Κρίσιμα σημεία ελέγχου και όρια","html":"<table><thead><tr><th>Στάδιο</th><th>Όριο</th><th>Έλεγχος</th></tr></thead><tbody>\n<tr><td>Παραλαβή ψυχόμενων</td><td>έως 5 °C</td><td>μέτρηση σε κάθε παραλαβή</td></tr>\n<tr><td>Παραλαβή κατεψυγμένων</td><td>−18 °C ή χαμηλότερα</td><td>μέτρηση σε κάθε παραλαβή</td></tr>\n<tr><td>Συντήρηση σε ψυγεία</td><td>0–5 °C</td><td>καταγραφή δύο φορές την ημέρα</td></tr>\n<tr><td>Μαγείρεμα</td><td>75 °C στο κέντρο του προϊόντος</td><td>θερμόμετρο ακίδας ανά παρτίδα</td></tr>\n<tr><td>Θερμή διατήρηση και διανομή</td><td>63 °C ή περισσότερο</td><td>μέτρηση πριν από τη διανομή</td></tr>\n<tr><td>Ψύξη μαγειρεμένων</td><td>κάτω από 10 °C σε έως 2 ώρες</td><td>καταγραφή χρόνου και θερμοκρασίας</td></tr>\n</tbody></table>\n<p class=\"reg-note\">Τα όρια επιβεβαιώνονται από την ομάδα HACCP με βάση τον εξοπλισμό και τους οδηγούς του ΕΦΕΤ.</p>"},{"id":"f-corrective","title":"Διορθωτικές ενέργειες και επαλήθευση","html":"<p>Όταν ένα όριο ξεπεραστεί, το προϊόν απομονώνεται, ο υπεύθυνος αποφασίζει αν θα επανεπεξεργαστεί ή θα απορριφθεί, και η απόκλιση καταγράφεται. Η ομάδα HACCP επαληθεύει κάθε μήνα τα αρχεία και κάθε χρόνο ολόκληρο το σύστημα.</p>"}]},{"id":"f-prerequisites","title":"Προαπαιτούμενα προγράμματα","sections":[{"id":"f-hygiene","title":"Υγιεινή προσωπικού","html":"<ul><li>Καθαρή στολή, κάλυμμα κεφαλής και, όπου χρειάζεται, γάντια μίας χρήσης.</li><li>Υγιεινή χεριών πριν από την εργασία, μετά από ωμά τρόφιμα, απορρίμματα και την τουαλέτα.</li><li>Απαγόρευση εργασίας με γαστρεντερικά συμπτώματα ή μολυσμένα τραύματα· δήλωση στον υπεύθυνο.</li><li>Ιατρικές εξετάσεις και πιστοποιητικό υγείας σύμφωνα με την ισχύουσα νομοθεσία.</li></ul>"},{"id":"f-cleaning","title":"Καθαρισμός, απεντόμωση, νερό","html":"<p>Εφαρμόζεται γραπτό πρόγραμμα καθαρισμού και απολύμανσης επιφανειών και εξοπλισμού, πρόγραμμα απεντόμωσης και μυοκτονίας από αδειοδοτημένο συνεργάτη, και έλεγχος της ποιότητας του νερού. Τα σκεύη και οι επιφάνειες για ωμά και μαγειρεμένα τρόφιμα διαχωρίζονται με κωδικοποίηση χρωμάτων.</p>"},{"id":"f-suppliers","title":"Προμηθευτές και ιχνηλασιμότητα","html":"<p>Οι προμηθευτές εγκρίνονται και αξιολογούνται κάθε χρόνο. Κάθε παρτίδα καταγράφεται κατά την παραλαβή ώστε να ιχνηλατείται και να ανακαλείται αν χρειαστεί. Κρατούνται δείγματα των γευμάτων για 72 ώρες, όπου το προβλέπει η διαδικασία.</p>"}]},{"id":"f-patients","title":"Διατροφή ασθενών","sections":[{"id":"f-diets","title":"Δίαιτες και αλλεργιογόνα","html":"<p>Η δίαιτα κάθε ασθενούς ορίζεται από τον θεράποντα ιατρό και τον διαιτολόγο και φαίνεται στο δελτίο του δίσκου. Τα 14 αλλεργιογόνα του Κανονισμού (ΕΕ) 1169/2011 σημαίνονται σε κάθε συνταγή. Τα γεύματα ειδικής δίαιτας ή χωρίς αλλεργιογόνα παρασκευάζονται και σημαίνονται χωριστά.</p>"},{"id":"f-distribution","title":"Διανομή στους θαλάμους","html":"<p>Τα γεύματα διανέμονται σε κλειστούς δίσκους ή θερμαινόμενα τρόλεϊ, εντός του χρόνου που ορίζει η ομάδα HACCP. Οι τραπεζοκόμοι ελέγχουν το όνομα και τη δίαιτα πριν από την παράδοση του δίσκου. Στους θαλάμους απομόνωσης ακολουθούνται οι οδηγίες της ΕΝΛ.</p>"},{"id":"f-feedback","title":"Γνώμη των ασθενών","html":"<p>Η ικανοποίηση από τη διατροφή μετριέται με την Έρευνα Κουζίνας του Κέντρου Ποιότητας. Ερωτήσεις κάτω από τον στόχο οδηγούν σε διορθωτική ενέργεια.</p>"}]}]}'::jsonb, 'Πρώτη έκδοση του προτύπου.')
on conflict (key) do nothing;
insert into public.regulation_template_versions (template_key, version, content, change_note, published_by)
select key, version, content, change_note, null from public.regulation_templates where key = 'food_safety'
on conflict (template_key, version) do nothing;

insert into public.regulation_templates (key, title, title_en, category, description, sources, version, content, change_note)
values ('water_safety', 'Σχέδιο Ασφάλειας Νερού και Πρόληψης Λεγιονέλλωσης', 'Water safety plan and Legionella prevention', 'infection', 'Εκτίμηση κινδύνου του δικτύου, θερμοκρασίες, ροή και συντήρηση, δειγματοληψίες, μέτρα σε θετικό αποτέλεσμα ή κρούσμα.', 'Οδηγίες ΕΟΔΥ και Υπουργείου Υγείας για τη νόσο των λεγεωναρίων · Ευρωπαϊκές τεχνικές οδηγίες ESGLI/ECDC · Σχέδια Ασφάλειας Νερού ΠΟΥ', 1, '{"chapters":[{"id":"wt-intro","title":"Εισαγωγή","sections":[{"id":"wt-purpose","title":"Σκοπός","html":"<p>Το Σχέδιο Ασφάλειας Νερού του {hospital} προλαμβάνει τη νόσο των λεγεωναρίων και τις λοιμώξεις που μεταδίδονται με το νερό (Pseudomonas, μη φυματιογόνα μυκοβακτήρια), μέσα από εκτίμηση κινδύνου, έλεγχο θερμοκρασιών, συντήρηση και δειγματοληψίες. Ασθενείς ηλικιωμένοι, ανοσοκατεσταλμένοι, σε ΜΕΘ ή μετά από μεταμόσχευση θεωρούνται υψηλού κινδύνου.</p>"},{"id":"wt-framework","title":"Πλαίσιο","html":"<ul><li>Οδηγίες και εγκύκλιοι του ΕΟΔΥ και του Υπουργείου Υγείας για την πρόληψη της νόσου των λεγεωναρίων.</li><li>Ευρωπαϊκές τεχνικές οδηγίες για την πρόληψη, τον έλεγχο και τη διερεύνηση λοιμώξεων από Legionella (ESGLI/ECDC).</li><li>Οδηγίες του Παγκόσμιου Οργανισμού Υγείας για τα Σχέδια Ασφάλειας Νερού.</li></ul>\n<p class=\"reg-note\">Επιβεβαιώστε τα όρια και τις συχνότητες με τις τρέχουσες οδηγίες του ΕΟΔΥ πριν από την έγκριση.</p>"}]},{"id":"wt-team","title":"Ομάδα και εκτίμηση κινδύνου","sections":[{"id":"wt-group","title":"Ομάδα ασφάλειας νερού","html":"<p>Η ομάδα (Τεχνική Υπηρεσία, ΕΝΛ, Ποιότητα, Διοίκηση) ενημερώνει το σχέδιο των εγκαταστάσεων, την εκτίμηση κινδύνου και το πρόγραμμα ελέγχων, και συνεδριάζει τουλάχιστον κάθε τρίμηνο.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τα μέλη της ομάδας και τον υπεύθυνο της Τεχνικής Υπηρεσίας.</p>"},{"id":"wt-risk","title":"Εκτίμηση κινδύνου","html":"<ul><li>Χάρτης του δικτύου ζεστού και κρύου νερού, δεξαμενών, θερμαντήρων και πύργων ψύξης.</li><li>Νεκρά σκέλη και σημεία με χαμηλή χρήση.</li><li>Σημεία δημιουργίας αερολύματος: ντουζ, βρύσες, υγραντήρες, συσκευές αναπνευστικής θεραπείας, μονάδες αιμοκάθαρσης.</li><li>Τμήματα με ασθενείς υψηλού κινδύνου.</li></ul>\n<p>Η εκτίμηση αναθεωρείται κάθε χρόνο, και πάντα μετά από αλλαγή στο δίκτυο ή μετά από κρούσμα.</p>"}]},{"id":"wt-control","title":"Μέτρα ελέγχου","sections":[{"id":"wt-temperatures","title":"Θερμοκρασίες","html":"<table><thead><tr><th>Σημείο</th><th>Στόχος</th><th>Έλεγχος</th></tr></thead><tbody>\n<tr><td>Αποθήκευση ζεστού νερού</td><td>60 °C ή περισσότερο</td><td>μηνιαία</td></tr>\n<tr><td>Επιστροφή ανακυκλοφορίας</td><td>τουλάχιστον 50 °C</td><td>μηνιαία</td></tr>\n<tr><td>Ζεστό νερό στη βρύση (μετά από 1 λεπτό)</td><td>τουλάχιστον 50 °C</td><td>σε δείγμα σημείων κάθε μήνα</td></tr>\n<tr><td>Κρύο νερό στη βρύση (μετά από 2 λεπτά)</td><td>κάτω από 20 °C</td><td>σε δείγμα σημείων κάθε μήνα</td></tr>\n</tbody></table>\n<p>Όπου υπάρχει κίνδυνος εγκαύματος τοποθετούνται θερμοστατικές βαλβίδες ανάμιξης κοντά στο σημείο χρήσης, με δική τους συντήρηση.</p>"},{"id":"wt-flushing","title":"Συντήρηση και ροή","html":"<ul><li>Εβδομαδιαία ροή στα σημεία που χρησιμοποιούνται σπάνια, με καταγραφή.</li><li>Αφαίρεση νεκρών σκελών κατά τις εργασίες.</li><li>Καθαρισμός και απολύμανση κεφαλών ντους και φίλτρων αερισμού βρύσης σε τακτά διαστήματα.</li><li>Συντήρηση πύργων ψύξης και κλιματιστικών σύμφωνα με τον κατασκευαστή και την εκτίμηση κινδύνου.</li><li>Φίλτρα σημείου χρήσης στα τμήματα υψηλού κινδύνου, όπου το ορίζει η ΕΝΛ.</li></ul>"}]},{"id":"wt-monitoring","title":"Δειγματοληψίες και αποτελέσματα","sections":[{"id":"wt-sampling","title":"Πρόγραμμα δειγματοληψιών","html":"<p>Δείγματα για Legionella λαμβάνονται από διαπιστευμένο εργαστήριο, σε σημεία που ορίζει η εκτίμηση κινδύνου (πιο απομακρυσμένα, υψηλού κινδύνου, δεξαμενές), με συχνότητα που ορίζει η ομάδα και τουλάχιστον όπως προβλέπουν οι οδηγίες του ΕΟΔΥ.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τα σημεία και τη συχνότητα δειγματοληψίας.</p>"},{"id":"wt-positive","title":"Θετικό αποτέλεσμα ή κρούσμα","html":"<ul><li>Άμεση ενημέρωση της ΕΝΛ και της Διοίκησης.</li><li>Περιορισμός της χρήσης των σημείων (π.χ. όχι ντουζ για ασθενείς υψηλού κινδύνου), φίλτρα σημείου χρήσης.</li><li>Θερμική ή χημική απολύμανση και επαναληπτικός έλεγχος.</li><li>Σε κρούσμα νοσοκομειακής λεγιονέλλωσης: δήλωση στον ΕΟΔΥ, επιδημιολογική διερεύνηση και καταγραφή ως συμβάν στο Κέντρο Ποιότητας.</li></ul>"}]}]}'::jsonb, 'Πρώτη έκδοση του προτύπου.')
on conflict (key) do nothing;
insert into public.regulation_template_versions (template_key, version, content, change_note, published_by)
select key, version, content, change_note, null from public.regulation_templates where key = 'water_safety'
on conflict (template_key, version) do nothing;

insert into public.regulation_templates (key, title, title_en, category, description, sources, version, content, change_note)
values ('sterilization', 'Κανονισμός Λειτουργίας Κεντρικής Αποστείρωσης', 'Central sterile services regulation', 'infection', 'Ζώνες και ροή, πλύσιμο, συσκευασία, αποστείρωση, δοκιμές και δείκτες, αποδέσμευση και ανάκληση, ιχνηλασιμότητα, ενδοσκόπια.', 'EN ISO 17664 · EN ISO 15883 · EN ISO 11607 · EN 285 · EN ISO 17665 · EN ISO 11140 · EN ISO 11138 · Ταξινόμηση Spaulding', 1, '{"chapters":[{"id":"st-intro","title":"Εισαγωγή","sections":[{"id":"st-purpose","title":"Σκοπός και πεδίο εφαρμογής","html":"<p>Ο Κανονισμός ορίζει πώς η Κεντρική Αποστείρωση του {hospital} επανεπεξεργάζεται τα επαναχρησιμοποιούμενα ιατροτεχνολογικά προϊόντα (εργαλεία, σετ, ενδοσκόπια), ώστε κάθε υλικό να φτάνει στον ασθενή καθαρό, λειτουργικό και αποστειρωμένο, με τεκμηρίωση που ιχνηλατείται.</p>"},{"id":"st-framework","title":"Πρότυπα","html":"<ul><li>EN ISO 17664: οδηγίες του κατασκευαστή για την επανεπεξεργασία.</li><li>EN ISO 15883: πλυντήρια-απολυμαντές (και μέρος 4 για τα εύκαμπτα ενδοσκόπια).</li><li>EN ISO 11607: συσκευασία για αποστείρωση.</li><li>EN 285 και EN ISO 17665: αποστείρωση με ατμό.</li><li>EN ISO 11140 και EN ISO 11138: χημικοί και βιολογικοί δείκτες.</li><li>Η ταξινόμηση Spaulding: κρίσιμα, ημικρίσιμα και μη κρίσιμα υλικά.</li></ul>"}]},{"id":"st-cycle","title":"Ο κύκλος επανεπεξεργασίας","sections":[{"id":"st-zones","title":"Ζώνες και ροή","html":"<p>Η Αποστείρωση χωρίζεται σε ακάθαρτη ζώνη (παραλαβή, απολύμανση, πλύσιμο), καθαρή ζώνη (έλεγχος, συσκευασία) και αποστειρωμένη ζώνη (αποθήκευση), με ροή μίας κατεύθυνσης και διαφορά πίεσης μεταξύ των ζωνών. Τα υλικά μεταφέρονται από τα χειρουργεία και τα τμήματα σε κλειστά καρότσια.</p>"},{"id":"st-cleaning","title":"Προκαθαρισμός, πλύσιμο, έλεγχος","html":"<ul><li>Τα υλικά διατηρούνται υγρά μετά τη χρήση και παραδίδονται το ταχύτερο δυνατόν.</li><li>Πλύσιμο σε επικυρωμένα πλυντήρια-απολυμαντές, με χειροκίνητο προκαθαρισμό όπου ορίζει ο κατασκευαστής.</li><li>Οπτικός έλεγχος καθαριότητας και λειτουργίας με μεγεθυντικό φακό· ό,τι δεν είναι καθαρό επιστρέφει στην αρχή.</li></ul>"},{"id":"st-packing","title":"Συσκευασία και αποστείρωση","html":"<p>Κάθε σετ συσκευάζεται με τον κατάλληλο τρόπο, με εσωτερικό χημικό δείκτη και ετικέτα (σετ, κύκλος, ημερομηνία, υπεύθυνος). Η μέθοδος αποστείρωσης ορίζεται από τον κατασκευαστή: ατμός στους 134 °C ή 121 °C, ή χαμηλή θερμοκρασία για θερμοευαίσθητα υλικά.</p>"}]},{"id":"st-control","title":"Έλεγχος ποιότητας","sections":[{"id":"st-tests","title":"Δοκιμές και δείκτες","html":"<table><thead><tr><th>Έλεγχος</th><th>Συχνότητα</th></tr></thead><tbody>\n<tr><td>Δοκιμή Bowie–Dick (διείσδυση ατμού)</td><td>κάθε ημέρα, πριν από τον πρώτο κύκλο</td></tr>\n<tr><td>Φυσικοί παράμετροι κύκλου (χρόνος, θερμοκρασία, πίεση)</td><td>κάθε κύκλο</td></tr>\n<tr><td>Χημικοί δείκτες</td><td>κάθε πακέτο</td></tr>\n<tr><td>Βιολογικοί δείκτες</td><td>όπως ορίζει η διαδικασία, και σε κάθε φορτίο με εμφυτεύματα</td></tr>\n<tr><td>Επικύρωση πλυντηρίων και αποστειρωτών</td><td>ετήσια</td></tr>\n</tbody></table>"},{"id":"st-release","title":"Αποδέσμευση και ανάκληση","html":"<p>Ένα φορτίο αποδεσμεύεται μόνο όταν όλοι οι έλεγχοι είναι εντός ορίων και καταγράφονται. Αν ένας δείκτης αποτύχει, το φορτίο ανακαλείται, ενημερώνονται τα τμήματα και, αν έχει ήδη χρησιμοποιηθεί, καταγράφεται συμβάν και ειδοποιείται ο υπεύθυνος ιατρός.</p>"},{"id":"st-storage","title":"Αποθήκευση και ιχνηλασιμότητα","html":"<p>Τα αποστειρωμένα υλικά αποθηκεύονται σε καθαρό, ξηρό χώρο, μακριά από το δάπεδο, με τη λογική «πρώτο μέσα, πρώτο έξω». Η στειρότητα εξαρτάται από τα συμβάντα και όχι μόνο από τον χρόνο: πακέτο υγρό, σκισμένο ή πεσμένο δεν χρησιμοποιείται. Κάθε σετ ιχνηλατείται έως τον ασθενή στον οποίο χρησιμοποιήθηκε.</p>\n<p class=\"reg-fill\">Συμπληρώστε: το σύστημα ιχνηλάτησης που χρησιμοποιείτε (ετικέτες, barcode).</p>"}]},{"id":"st-endoscopes","title":"Ενδοσκόπια","sections":[{"id":"st-endo","title":"Επανεπεξεργασία εύκαμπτων ενδοσκοπίων","html":"<ul><li>Καθαρισμός στο σημείο χρήσης αμέσως μετά την εξέταση.</li><li>Δοκιμή στεγανότητας, χειροκίνητος καθαρισμός καναλιών με βούρτσες μίας χρήσης.</li><li>Υψηλού βαθμού απολύμανση σε πλυντήριο ενδοσκοπίων και ξήρανση των καναλιών.</li><li>Αποθήκευση σε ερμάρια ξήρανσης ή κάθετα, σε καθαρό χώρο.</li><li>Περιοδικές μικροβιολογικές καλλιέργειες, σύμφωνα με τη διαδικασία της ΕΝΛ.</li></ul>"}]},{"id":"st-people","title":"Προσωπικό και αρμοδιότητες","sections":[{"id":"st-staff","title":"Εκπαίδευση και προστασία","html":"<p>Το προσωπικό εκπαιδεύεται πριν από την ανάληψη καθηκόντων και κάθε χρόνο, φορά τα μέσα ατομικής προστασίας της ακάθαρτης ζώνης (ποδιά αδιάβροχη, γάντια, προστασία ματιών) και εμβολιάζεται για ηπατίτιδα Β. Ο υπεύθυνος της Αποστείρωσης παρακολουθεί τους δείκτες και συνεργάζεται με την ΕΝΛ και τα χειρουργεία.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τον υπεύθυνο της Κεντρικής Αποστείρωσης και τον αναπληρωτή του.</p>"}]}]}'::jsonb, 'Πρώτη έκδοση του προτύπου.')
on conflict (key) do nothing;
insert into public.regulation_template_versions (template_key, version, content, change_note, published_by)
select key, version, content, change_note, null from public.regulation_templates where key = 'sterilization'
on conflict (template_key, version) do nothing;

insert into public.regulation_templates (key, title, title_en, category, description, sources, version, content, change_note)
values ('patient_safety', 'Κανονισμός Ασφάλειας Ασθενών', 'Patient safety regulation', 'safety', 'Αναγνώριση ασθενούς, ασφάλεια φαρμάκων, ασφαλής χειρουργική, πτώσεις και κατακλίσεις, παράδοση, αναφορά και διερεύνηση συμβάντων, κουλτούρα ασφάλειας.', 'Ν. 4715/2020 (ΟΔΙΠΥ), όπως ισχύει · Παγκόσμιο Σχέδιο Δράσης για την Ασφάλεια των Ασθενών 2021–2030 (ΠΟΥ) · Λίστα Ελέγχου Ασφαλούς Χειρουργικής (ΠΟΥ) · ISO 9001', 1, '{"chapters":[{"id":"ps-intro","title":"Εισαγωγή","sections":[{"id":"ps-purpose","title":"Σκοπός","html":"<p>Ο Κανονισμός ορίζει τα μέτρα με τα οποία το {hospital} προλαμβάνει την πρόκληση βλάβης στους ασθενείς κατά τη φροντίδα, μαθαίνει από τα συμβάντα και καλλιεργεί κουλτούρα ασφάλειας χωρίς απόδοση ευθύνης.</p>"},{"id":"ps-framework","title":"Πλαίσιο","html":"<ul><li>Ν. 4715/2020: ίδρυση του Οργανισμού Διασφάλισης της Ποιότητας στην Υγεία (ΟΔΙΠΥ), όπως ισχύει.</li><li>Παγκόσμιο Σχέδιο Δράσης για την Ασφάλεια των Ασθενών 2021–2030 του Παγκόσμιου Οργανισμού Υγείας.</li><li>Λίστα Ελέγχου Ασφαλούς Χειρουργικής του Παγκόσμιου Οργανισμού Υγείας.</li><li>ISO 9001: σύστημα διαχείρισης ποιότητας.</li></ul>\n<p class=\"reg-fill\">Συμπληρώστε: τυχόν απαιτήσεις διαπίστευσης που εφαρμόζετε.</p>"}]},{"id":"ps-practices","title":"Πρακτικές ασφάλειας","sections":[{"id":"ps-identification","title":"Σωστή αναγνώριση του ασθενούς","html":"<p>Η ταυτότητα του ασθενούς επιβεβαιώνεται με τουλάχιστον δύο στοιχεία (ονοματεπώνυμο και ημερομηνία γέννησης), ποτέ με τον αριθμό του θαλάμου, πριν από κάθε φάρμακο, μετάγγιση, λήψη δείγματος, εξέταση ή επέμβαση. Κάθε ασθενής φορά βραχιόλι ταυτοποίησης από την εισαγωγή του.</p>"},{"id":"ps-medication","title":"Ασφάλεια φαρμάκων","html":"<ul><li>Οι «πέντε σωστοί κανόνες»: σωστός ασθενής, φάρμακο, δόση, οδός, χρόνος.</li><li>Λίστα φαρμάκων υψηλού κινδύνου (π.χ. ινσουλίνη, αντιπηκτικά, πυκνό κάλιο, οπιοειδή) με διπλό έλεγχο από δεύτερο επαγγελματία.</li><li>Φάρμακα με παρόμοια όψη ή όνομα φυλάσσονται χωριστά και σημαίνονται.</li><li>Συμφιλίωση της φαρμακευτικής αγωγής κατά την εισαγωγή, τη μεταφορά και την έξοδο.</li></ul>"},{"id":"ps-surgery","title":"Ασφαλής χειρουργική","html":"<p>Σε κάθε επέμβαση εφαρμόζεται η Λίστα Ελέγχου Ασφαλούς Χειρουργικής σε τρία σημεία: πριν από την αναισθησία (sign in), πριν από την τομή (time out) και πριν ο ασθενής φύγει από την αίθουσα (sign out). Η θέση της επέμβασης σημαίνεται πριν από τη μεταφορά στο χειρουργείο.</p>"},{"id":"ps-falls","title":"Πτώσεις και κατακλίσεις","html":"<p>Κατά την εισαγωγή και σε κάθε αλλαγή της κατάστασης εκτιμώνται ο κίνδυνος πτώσης (π.χ. κλίμακα Morse) και ο κίνδυνος κατάκλισης (κλίμακα Braden), και εφαρμόζονται τα αντίστοιχα μέτρα: χαμηλό κρεβάτι, πλαϊνά, συνοδεία στην κινητοποίηση· αλλαγή θέσης, στρώματα κατανομής πίεσης, φροντίδα του δέρματος.</p>"},{"id":"ps-handover","title":"Επικοινωνία και παράδοση","html":"<p>Η παράδοση μεταξύ βαρδιών και κατά τη μεταφορά του ασθενούς γίνεται με δομημένο τρόπο (SBAR: κατάσταση, ιστορικό, εκτίμηση, σύσταση). Τα κρίσιμα εργαστηριακά αποτελέσματα ανακοινώνονται άμεσα στον υπεύθυνο ιατρό και η ενημέρωση καταγράφεται.</p>"}]},{"id":"ps-events","title":"Συμβάντα","sections":[{"id":"ps-reporting","title":"Αναφορά και διερεύνηση","html":"<ul><li>Κάθε εργαζόμενος αναφέρει συμβάντα και παρ'' ολίγον συμβάντα στο Κέντρο Ποιότητας, και ανώνυμα αν το επιθυμεί.</li><li>Τα σοβαρά ανεπιθύμητα συμβάντα (sentinel) ενημερώνουν αμέσως τη Διοίκηση και διερευνώνται με ανάλυση αιτίων (RCA).</li><li>Κάθε διερεύνηση καταλήγει σε διορθωτικές ενέργειες, με υπεύθυνο, προθεσμία και έλεγχο αποτελεσματικότητας.</li><li>Ο ασθενής και η οικογένειά του ενημερώνονται με ειλικρίνεια για ένα συμβάν που τους αφορά.</li></ul>"},{"id":"ps-learning","title":"Μάθηση από τα συμβάντα","html":"<p>Τα συμβάντα και οι δείκτες ασφάλειας παρουσιάζονται στις Συναντήσεις των τμημάτων και στην Ανασκόπηση της Διοίκησης. Τα διδάγματα κοινοποιούνται χωρίς στοιχεία προσώπων, ώστε να μη χρειαστεί να επαναληφθεί το ίδιο λάθος.</p>"}]},{"id":"ps-culture","title":"Κουλτούρα ασφάλειας","sections":[{"id":"ps-measure","title":"Μέτρηση και στόχοι","html":"<p>Η κουλτούρα ασφάλειας μετριέται με έρευνα στο προσωπικό τουλάχιστον κάθε δύο χρόνια. Οι δείκτες (πτώσεις ανά 1.000 ημέρες νοσηλείας, κατακλίσεις, φαρμακευτικά λάθη, τήρηση της χειρουργικής λίστας) παρακολουθούνται μηνιαία με στόχους στο Κέντρο Ποιότητας.</p>\n<p class=\"reg-fill\">Συμπληρώστε: τους στόχους του τρέχοντος έτους.</p>"}]}]}'::jsonb, 'Πρώτη έκδοση του προτύπου.')
on conflict (key) do nothing;
insert into public.regulation_template_versions (template_key, version, content, change_note, published_by)
select key, version, content, change_note, null from public.regulation_templates where key = 'patient_safety'
on conflict (template_key, version) do nothing;
